// ListGuestHistory is the timeline: one page of a guest's entries, newest
// first, with the total under the same filters.
//
// Entries, one per thing that happened:
//
//	audit    an audit row naming the guest: by vmid (000084); a clone INTO it,
//	         which names its source (see ListGuestLifecycleEvents); or an HA
//	         resource row, which names the guest only by its HA sid ("vm:100",
//	         "ct:100") and so carries no vmid. A Proxmox-ingested row is
//	         dropped when a Nexara row carries the same UPID: the collector's
//	         dedupe can lose a race with a handler's own insert, and the two
//	         rows are one task, the Nexara one the one that says who asked.
//	task     a guest task with NO audit row, from task_history or its archive
//	         — only when include_tasks, which the handler sets from view:task.
//	         Every task path writes an audit row too, so this is the rare row
//	         whose audit insert failed; sharing a UPID with an audit row makes
//	         a task the same entry, never a second one.
//	status   a status change no task explains (ClassifyGuestStatusChanges),
//	         for the guest types in status_guest_types — the run state is
//	         inventory data, which the handler reads under view:vm for a VM and
//	         view:container for a container.
//	backup   the guest's part of a backup JOB (guest_backups), with the
//	         guest's own outcome and times rather than the job's — only when
//	         include_tasks, since all of it is read from the job's task log.
//	         A job's own audit row names no guest, so it is never a second
//	         entry; nor is its task row, whose vmid is NULL.
//
// Guest tasks only: is_guest_upid, never vmid alone, because InsertTaskHistory
// stamps a vmid on any numeric worker id — cephdestroyosd's is an OSD number,
// so "destroy OSD 113" would otherwise read as something done to VM 113.
// audit_log.vmid is already gated the same way at insert.
//
// guest_audit is three branches rather than one OR, so each reads its own
// index — the vmid arm (cluster_id, vmid), the clone arm the action index, the
// HA arm the resource_type index — instead of the planner settling on the
// whole cluster's rows. The second and third exclude the first's rows, so no
// row is read twice. The Proxmox-duplicate probe is scoped to the same guest
// by parameter, not by correlation: correlated on the UPID alone, the planner
// hashes every Nexara row the install has ever written, on every request.
//
// after/after_inclusive is the cutoff guestHistoryCutoff derived from
// ListGuestLifecycleEvents: inclusive from a birth, so the create or clone is
// the first entry; exclusive after a destroy, so the previous guest's last act
// is not this one's first.
//
// category is derived HERE, once, so it can be filtered on before the page is
// cut; the handler's guestHistoryCategories lists the same values (pinned by
// TestGuestHistoryCategoryVocabulary). Nexara's own action names are matched
// before the Proxmox worker type, because they are the more specific of the
// two: DRS asks an HA-managed guest to migrate through an hamigrate task, and
// that is a migration. A start or stop of an HA-managed guest runs as hastart
// or hastop, from Nexara or the Proxmox GUI alike, and is a power action; 'ha'
// is what is left — the guest's HA resource itself. Unmatched is 'other' —
// still listed, under its own action name.
//
// The page is cut on narrow rows, and only its rows are joined to their audit
// details, task outcome and user: a guest with ten thousand entries carries
// ten thousand jsonb blobs through the sort otherwise. A backup entry's
// outcome, end and log lines are the guest's own, from guest_backups; the
// job's own task row, joined like any other, gives the rest. total is
// count(*) OVER the filtered set, computed before LIMIT — the Items and the
// Total come from one query and so cannot be counted under different filters.
func (q *Queries) ListGuestHistory(ctx context.Context, arg ListGuestHistoryParams) ([]ListGuestHistoryRow, error) {
	rows, err := q.db.Query(ctx, listGuestHistory,
		arg.ClusterID,
		arg.Vmid,
		arg.IncludeTasks,
		arg.StatusGuestTypes,
		arg.After,
		arg.AfterInclusive,
		arg.Since,
		arg.Category,
		arg.Source,
		arg.RowOffset,
		arg.RowLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListGuestHistoryRow{}
	for rows.Next() {
		var i ListGuestHistoryRow
		if err := rows.Scan(
			&i.EntryID,
			&i.Kind,
			&i.OccurredAt,
			&i.Source,
			&i.Action,
			&i.ResourceType,
			&i.ResourceID,
			&i.Vmid,
			&i.UserID,
			&i.Upid,
			&i.Node,
			&i.RecordedStatus,
			&i.FromStatus,
			&i.ToStatus,
			&i.LastSeenAt,
			&i.Category,
			&i.Total,
			&i.Details,
			&i.UserEmail,
			&i.UserDisplayName,
			&i.TaskStatus,
			&i.TaskExitStatus,
			&i.TaskDescription,
			&i.TaskType,
			&i.TaskNode,
			&i.TaskProgress,
			&i.TaskFinishedAt,
			&i.BackupFinishedAt,
			&i.LogStart,
			&i.LogEnd,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listGuestLifecycleEvents = `-- name: ListGuestLifecycleEvents :many
SELECT a.created_at,
       COALESCE(split_part(a.details->>'upid', ':', 6) IN ('qmdestroy', 'vzdestroy'), false)::bool AS is_destroy,
       COALESCE(th.status, ar.status, '')::text                                   AS task_status,
       COALESCE(th.exit_status, ar.exit_status, '')::text                         AS task_exit_status,
       COALESCE(a.details->>'status', '')::text                                   AS recorded_status
FROM audit_log a
LEFT JOIN task_history th
       ON th.upid = a.details->>'upid' AND th.cluster_id = a.cluster_id
LEFT JOIN task_history_archive ar
       ON ar.upid = a.details->>'upid' AND ar.cluster_id = a.cluster_id
WHERE a.cluster_id = $1
  AND (
        (a.vmid = $2::int
         AND split_part(a.details->>'upid', ':', 6) IN ('qmcreate', 'vzcreate', 'qmrestore',
                                                        'vzrestore', 'qmdestroy', 'vzdestroy'))
     OR (a.action IN ('clone', 'clone-to-template')
         AND a.details->>'new_id' = $2::int::text)
  )
ORDER BY a.created_at DESC, a.id
LIMIT 50
`

type ListGuestLifecycleEventsParams struct {
	ClusterID pgtype.UUID `json:"cluster_id"`
	Vmid      int32       `json:"vmid"`
}

type ListGuestLifecycleEventsRow struct {
	CreatedAt      time.Time `json:"created_at"`
	IsDestroy      bool      `json:"is_destroy"`
	TaskStatus     string    `json:"task_status"`
	TaskExitStatus string    `json:"task_exit_status"`
	RecordedStatus string    `json:"recorded_status"`
}

// ListGuestLifecycleEvents returns the audit rows that begin or end a guest's
// occupancy of a VMID, newest first, for the handler to pick where the
// timeline starts (guestHistoryCutoff). Proxmox hands out the lowest free
// VMID, so VM 105 today may be the third guest to hold that number, and
// without a cutoff the first two guests' history would read as this one's.
//
// A birth is a create or restore of the VMID — by the UPID's worker type,
// which both Nexara's handlers and the collector's ingest record — or a clone
// INTO it. A clone's UPID names its SOURCE, so the target is read from the
// new_id the clone handlers record; a clone made in Proxmox's own GUI records
// no target and is no birth here, which leaves the previous occupant's destroy
// as the cutoff instead.
//
// A destroy comes back with its outcome, because a FAILED destroy ended
// nothing; the handler decides with proxmox.TaskSucceeded rather than a SQL
// copy of that rule. recorded_status is the status the collector stored when
// it ingested a task, for a task whose row has since been pruned.
//
// Bounded: the handler only needs the newest birth and the newest destroy that
// did not fail, and a guest restored nightly would otherwise drag in a year of
// restores.
func (q *Queries) ListGuestLifecycleEvents(ctx context.Context, arg ListGuestLifecycleEventsParams) ([]ListGuestLifecycleEventsRow, error) {
	rows, err := q.db.Query(ctx, listGuestLifecycleEvents, arg.ClusterID, arg.Vmid)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListGuestLifecycleEventsRow{}
	for rows.Next() {
		var i ListGuestLifecycleEventsRow
		if err := rows.Scan(
			&i.CreatedAt,
			&i.IsDestroy,
			&i.TaskStatus,
			&i.TaskExitStatus,
			&i.RecordedStatus,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listUnreadBackupJobs = `-- name: ListUnreadBackupJobs :many
SELECT th.upid, th.node, th.started_at, th.finished_at,
       COALESCE(n.timezone, '')::text AS timezone,
       (th.updated_at < $1::timestamptz)::bool AS last_try
FROM task_history th
LEFT JOIN nodes n ON n.cluster_id = th.cluster_id AND n.name = th.node
WHERE th.cluster_id = $2
  AND th.vmid IS NULL
  AND split_part(th.upid, ':', 6) = 'vzdump'
  AND th.status <> 'running'
  AND th.node = split_part(th.upid, ':', 2)
  AND th.node = ANY($3::text[])
  AND NOT EXISTS (SELECT 1 FROM backup_job_logs l WHERE l.upid = th.upid)
ORDER BY last_try DESC, th.started_at DESC
LIMIT $4::int
`

type ListUnreadBackupJobsParams struct {
	GiveUpBefore time.Time `json:"give_up_before"`
	ClusterID    uuid.UUID `json:"cluster_id"`
	ListedNodes  []string  `json:"listed_nodes"`
	MaxJobs      int32     `json:"max_jobs"`
}

type ListUnreadBackupJobsRow struct {
	Upid       string             `json:"upid"`
	Node       string             `json:"node"`
	StartedAt  time.Time          `json:"started_at"`
	FinishedAt pgtype.Timestamptz `json:"finished_at"`
	Timezone   string             `json:"timezone"`
	LastTry    bool               `json:"last_try"`
}

// The collector's reading of backup JOB logs (internal/collector/
// backup_job_log.go): the finished jobs still to read, the ones it can no
// longer read, and the write of one job's result.
//
// A job is a finished vzdump in task_history whose UPID names no guest (vmid
// NULL) and that has no backup_job_logs mark yet. Its log is on the node its
// UPID names, and only a row filed under that node is read: the collector
// asks the row's node, as the reconciler does. Every writer files a task under
// the node its UPID names — POST /api/v1/tasks refuses any other, though it
// takes no node at all — so a row that does not is never read, only
// abandoned.
//
// give_up_before bounds how long a job is tried for, counted from when its
// row last changed: updated_at, which the row's trigger sets on every write —
// when the collector saw the job finish, or ingested it finished already,
// which for a job that ran while Nexara was down is once Nexara is back, so
// it gets its full time from then rather than none. Not finished_at, which
// PUT /api/v1/tasks/:upid lets a caller set to any time. Past it, a job on a
// listed node is read one last time and recorded with whatever its log gave
// (last_try); one whose node is not listed this pass is marked unread.
//
// Last tries come first, so they cannot be starved by newer jobs whose reads
// keep failing; then newest first, so a job that just ended is read in the
// pass after it ends.
func (q *Queries) ListUnreadBackupJobs(ctx context.Context, arg ListUnreadBackupJobsParams) ([]ListUnreadBackupJobsRow, error) {
	rows, err := q.db.Query(ctx, listUnreadBackupJobs,
		arg.GiveUpBefore,
		arg.ClusterID,
		arg.ListedNodes,
		arg.MaxJobs,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListUnreadBackupJobsRow{}
	for rows.Next() {
		var i ListUnreadBackupJobsRow
		if err := rows.Scan(
			&i.Upid,
			&i.Node,
			&i.StartedAt,
			&i.FinishedAt,
			&i.Timezone,
			&i.LastTry,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const recordBackupJobLog = `-- name: RecordBackupJobLog :exec
WITH job AS (
    SELECT th.upid, th.cluster_id, th.node, th.source, th.user_id
    FROM task_history th
    WHERE th.upid = $2 AND th.cluster_id = $3
), guests AS (
    INSERT INTO guest_backups (upid, vmid, cluster_id, node, source, user_id, status, exit_status,
                               started_at, finished_at, log_start, log_end)
    SELECT job.upid, g.vmid, job.cluster_id, job.node, job.source, job.user_id, g.status,
           g.exit_status, g.started_at, g.finished_at, g.log_start, g.log_end
    FROM job
    CROSS JOIN jsonb_to_recordset($4::jsonb) AS g(
        vmid int, status text, exit_status text, started_at timestamptz,
        finished_at timestamptz, log_start int, log_end int)
    ON CONFLICT (cluster_id, upid, vmid) DO NOTHING
)
INSERT INTO backup_job_logs (upid, log_read)
SELECT job.upid, $1::text
FROM job
ON CONFLICT (upid) DO NOTHING
`

type RecordBackupJobLogParams struct {
	LogRead   string          `json:"log_read"`
	Upid      string          `json:"upid"`
	ClusterID uuid.UUID       `json:"cluster_id"`
	Guests    json.RawMessage `json:"guests"`
}

// RecordBackupJobLog writes one job's guests and its mark in one statement,
// so a job is never marked without its guests, nor its guests written and the
// job left to be read again. Each guest's node, source and user are the job's
// own, from its task row, which the cluster_id must match: the write lands
// only on the cluster whose collector read the log.
func (q *Queries) RecordBackupJobLog(ctx context.Context, arg RecordBackupJobLogParams) error {
	_, err := q.db.Exec(ctx, recordBackupJobLog,
		arg.LogRead,
		arg.Upid,
		arg.ClusterID,
		arg.Guests,
	)
	return err
}
